// 함수 내부는 절차적이지만, 외부에는 선언적 인터페이스를 제공
function groupBy(array, keyFn) {         // ← 추상화 (선언적 인터페이스)
  const result = {};
  for (const item of array) {           // ← 내부 구현 (절차적)
    const key = keyFn(item);
    if (!result[key]) result[key] = [];
    result[key].push(item);
  }
  return result;
}

// 사용하는 쪽은 선언적
